"""Medieval furniture for the capitals (the user, 2026-11-11: no furniture mod runs on a Paper server, so the plugin
shows its own models through the resource pack). Every piece is a list of boxes in sixteenths of a block; the block it
stands in is 0..16 on each axis and a piece may reach from -16 to 32. THE FRONT IS NORTH (-z): a chair's back, a
cupboard's back and anything that hangs on a wall are at the south side (z = 16).

Textures are the game's own block textures, so the furniture follows whatever texture pack the player wears and
matches the houses. Letters: w planks, l beam, c cloth, r second cloth, m iron, d dark iron, g gold, s stone, x wax,
f flame (glows), k barrel side, t barrel top, b books, p pot, h hay, q parchment, C carved wood, T gold braid, W linen,
z water, i marble, a fruit; E the kingdom's device, K a keyboard, G an open book, D a door panel (these four are
stretched over one face). The textures themselves are painted in textures.py (2026-11-11 22:18: the game's plain block
textures looked flat on furniture).
"""

TEX = {
    'gf': dict(w='dark_oak_planks', l='dark_oak_log', c='blue_wool', r='red_wool', s='stone_bricks'),
    'sh': dict(w='spruce_planks', l='spruce_log', c='cyan_wool', r='white_wool', s='cobblestone'),
}
COMMON = dict(m='iron_block', d='anvil', g='gold_block', x='quartz_block_side', f='ochre_froglight_side', k='barrel_side',
              t='barrel_top', b='bookshelf', p='terracotta', h='hay_block_side', q='birch_planks', e='magma', n='coal_block',
              y='yellow_wool', o='brown_wool', v='green_wool', u='purple_wool')


def box(x0, y0, z0, x1, y1, z1, tex, over=None, rot=None, glow=False):
    return dict(a=(x0, y0, z0), b=(x1, y1, z1), tex=tex, over=over or {}, rot=rot, glow=glow)


def legs(x0, z0, x1, z1, h, t=2, tex='l', y0=0):
    return [box(x, y0, z, x + t, h, z + t, tex) for x in (x0, x1 - t) for z in (z0, z1 - t)]


def candle(x, y, z, h=4):
    return [box(x, y, z, x + 1.5, y + h, z + 1.5, 'x'), box(x + 0.4, y + h, z + 0.4, x + 1.1, y + h + 1.5, z + 1.1, 'f', glow=True)]


def mug(x, y, z):
    return [box(x, y, z, x + 2, y + 2.5, z + 2, 'k', over={'up': 't'}), box(x + 2, y + 0.7, z + 0.7, x + 2.6, y + 2, z + 1.3, 'k')]


def bottle(x, y, z, tex):
    return [box(x, y, z, x + 2, y + 2.5, z + 2, tex), box(x + 0.6, y + 2.5, z + 0.6, x + 1.4, y + 4, z + 1.4, 'x')]


